#pragma once

#include <array>
#include <string>

namespace kindergarten_garden {

enum class Plants {
    grass,
    clover,
    radishes,
    violets
};

class Garden {
public:
    explicit Garden(std::string diagram);

    std::array<Plants, 4> plants(const std::string& student) const;

private:
    std::array<std::string, 2> rows_;
};

}  // namespace kindergarten_garden
